#!/usr/bin/env python3
"""Generate a multi-instance Cloudflare WARP SOCKS5 docker-compose.yml.

Each container gets its own WARP identity (separate data volume) and exposes
a local SOCKS5 port. Designed so farm tools / browsers can round-robin exits.
"""
from __future__ import annotations

import argparse
import textwrap
from pathlib import Path


DEFAULT_IMAGE = "caomingjun/warp:latest"


def render_compose(
    *,
    count: int,
    base_port: int,
    bind: str,
    image: str,
    sleep: int,
    name_prefix: str,
) -> str:
    lines = [
        "# AUTO-GENERATED by scripts/generate-compose.py — edit via generator, not by hand.",
        f"# {count} independent Cloudflare WARP exits as SOCKS5 proxies.",
        f"# Ports: {base_port}..{base_port + count - 1}  bind={bind}",
        "services:",
    ]
    for i in range(1, count + 1):
        port = base_port + i - 1
        name = f"{name_prefix}{i}"
        lines.extend(
            [
                f"  {name}:",
                f"    image: {image}",
                f"    container_name: {name}",
                "    restart: unless-stopped",
                "    devices:",
                "      - /dev/net/tun:/dev/net/tun",
                "    cap_add:",
                "      - NET_ADMIN",
                "    environment:",
                f"      - WARP_SLEEP={sleep}",
                "    ports:",
                f'      - "{bind}:{port}:1080"',
                "    volumes:",
                f"      - ./data-n{i}:/var/lib/cloudflare-warp",
                "    # healthcheck uses the container's SOCKS listener",
                "    healthcheck:",
                '      test: ["CMD-SHELL", "curl -fsS --max-time 8 --proxy socks5h://127.0.0.1:1080 https://www.cloudflare.com/cdn-cgi/trace | grep -q warp=on || exit 1"]',
                "      interval: 60s",
                "      timeout: 15s",
                "      retries: 3",
                "      start_period: 45s",
            ]
        )
    lines.append("")
    return "\n".join(lines)


def main() -> int:
    p = argparse.ArgumentParser(
        description="Generate multi-WARP docker-compose.yml",
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=textwrap.dedent(
            """\
            Examples:
              # 10 local-only exits on 40001-40010 (recommended default)
              python3 scripts/generate-compose.py -n 10 -o docker-compose.yml

              # 5 exits bound on all interfaces (put behind firewall / Tailscale)
              python3 scripts/generate-compose.py -n 5 --bind 0.0.0.0 -o docker-compose.yml

              # Custom port base
              python3 scripts/generate-compose.py -n 3 --base-port 50001
            """
        ),
    )
    p.add_argument("-n", "--count", type=int, default=10, help="Number of WARP nodes (default: 10)")
    p.add_argument("--base-port", type=int, default=40001, help="First host port (default: 40001)")
    p.add_argument(
        "--bind",
        default="127.0.0.1",
        help="Host bind address. Prefer 127.0.0.1. Use 0.0.0.0 only with firewall (default: 127.0.0.1)",
    )
    p.add_argument("--image", default=DEFAULT_IMAGE, help=f"Docker image (default: {DEFAULT_IMAGE})")
    p.add_argument("--sleep", type=int, default=2, help="WARP_SLEEP seconds (default: 2)")
    p.add_argument("--name-prefix", default="warp-n", help="Container name prefix (default: warp-n)")
    p.add_argument("-o", "--output", type=Path, default=Path("docker-compose.yml"), help="Output path")
    p.add_argument("--stdout", action="store_true", help="Print to stdout instead of writing a file")
    args = p.parse_args()

    if args.count < 1 or args.count > 64:
        p.error("count must be between 1 and 64")
    if args.base_port < 1024 or args.base_port > 65000:
        p.error("base-port out of sane range")

    text = render_compose(
        count=args.count,
        base_port=args.base_port,
        bind=args.bind,
        image=args.image,
        sleep=args.sleep,
        name_prefix=args.name_prefix,
    )
    if args.stdout:
        print(text, end="")
    else:
        args.output.write_text(text)
        print(f"Wrote {args.output}  ({args.count} nodes, ports {args.base_port}-{args.base_port + args.count - 1}, bind={args.bind})")
        print(f"Next:  mkdir -p " + " ".join(f"data-n{i}" for i in range(1, args.count + 1)))
        print("       docker compose up -d")
        print(f"       ./scripts/healthcheck.sh --base-port {args.base_port} --count {args.count}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
